DIFF_NAMES = "easy|medium|difficult|hard|expert|scenario"


def php_escape(s: str) -> str:
    return s.replace("\\", "\\\\").replace("'", "\\'")


def php_unescape(s: str) -> str:
    return bytes(s, "utf-8").decode("unicode_escape") if False else s.replace("\\'", "'").replace("\\\\", "\\")


def parse_existing() -> dict[str, list[tuple]]:
    if OUT.exists():
        text = OUT.read_text(encoding="utf-8")
        pat = re.compile(
            rf"syncpediaBasicsMcq\('([^']+)', '({DIFF_NAMES})', '((?:\\.|[^'\\])*)', '((?:\\.|[^'\\])*)', '((?:\\.|[^'\\])*)', '((?:\\.|[^'\\])*)', '((?:\\.|[^'\\])*)', '([abcd])'\)",
        )
        out: dict[str, list[tuple]] = defaultdict(list)
        for m in pat.findall(text):
            domain, diff, p, a, b, c, d, ans = m
            if domain == "aptitude":
                continue
            out[domain].append(
                (diff, php_unescape(p), php_unescape(a), php_unescape(b), php_unescape(c), php_unescape(d), ans)
            )
        if sum(len(v) for v in out.values()) >= 90:
            return out
    text = PHP_SRC.read_text(encoding="utf-8")
    start = text.find("function syncpediaBasicsQuestionDefs")
    end = text.find("function syncpediaAssignmentQuestionDefs")
    chunk = text[start:end]
    parts = re.split(r"\$d\s*=\s*'([^']+)'\s*;", chunk)
    pat = re.compile(
        rf"syncpediaBasicsMcq\(\$d,\s*'({DIFF_NAMES})',\s*'((?:\\.|[^'\\])*)',\s*'((?:\\.|[^'\\])*)',\s*'((?:\\.|[^'\\])*)',\s*'((?:\\.|[^'\\])*)',\s*'((?:\\.|[^'\\])*)',\s*'([abcd])'\)",
    )
    out: dict[str, list[tuple]] = defaultdict(list)
    it = iter(parts[1:])
    while True:
        try:
            domain = next(it)
            body = next(it)
        except StopIteration:
            break
        for m in pat.findall(body):
            diff, p, a, b, c, d, ans = m
            out[domain].append(
                (diff, php_unescape(p), php_unescape(a), php_unescape(b), php_unescape(c), php_unescape(d), ans)
            )
    return out


def q(diff, prompt, a, b, c, d, ans="a"):
    return (diff, prompt, a, b, c, d, ans)


def nearest(diff, topic, correct, w1, w2, w3, ans="a"):
    prompt = (
        f"{topic} is nearest to which neighbouring claim, versus the neighbouring misreadings that are often collapsed into it?"
    )
    return q(diff, prompt, correct, w1, w2, w3, ans)


